#!/bin/zsh
# Local development build of TimeLock.app for the Mac (this Mac's architecture
# only). No Xcode required — Command Line Tools are enough. To ship a release to
# everyone's in-app updater, bump VERSION + RELEASE_NOTES.txt and push; the
# GitHub Action runs ./release.sh.
set -e
cd "$(dirname "$0")"
VERSION=$(cat VERSION)
BUILT=$(date "+%b %d, %H:%M")
FEED="${UPDATE_FEED-https://raw.githubusercontent.com/jonpikereally/TimeLock/main/updates/mac/latest.json}"
cat > Sources/TimeLock/Version.swift <<SWIFT
// Generated by build.sh / release.sh — do not edit.
enum AppVersion {
    static let version = "$VERSION"
    static let built = "$BUILT"
    static let updateFeed = "$FEED"
}
SWIFT
CACHE="${TMPDIR:-/tmp}/timelock-modcache"
mkdir -p "$CACHE" TimeLock.app/Contents/MacOS
cp Resources/Info.plist TimeLock.app/Contents/Info.plist
/usr/libexec/PlistBuddy -c "Set :CFBundleShortVersionString $VERSION" TimeLock.app/Contents/Info.plist
swiftc -O -module-cache-path "$CACHE" -o TimeLock.app/Contents/MacOS/TimeLock Sources/TimeLock/*.swift
codesign --force --sign - TimeLock.app
echo "Built TimeLock.app v$VERSION ($BUILT)"
